function daysToFinish(tasks: number[], space: number): number {
  const last = new Map<number, number>();
  let day = 0, i = 0;
  while (i < tasks.length) {
    day++;
    const k = tasks[i];
    if (!last.has(k) || day - last.get(k)! > space) {
      last.set(k, day);
      i++;
    }
  }
  return day;
}

