function daysToFinish(tasks: number[], space: number): number {
  const last = new Map<number, number>();
  let day = 0;
  for (const k of tasks) {
    day++;
    const prev = last.get(k);
    if (prev !== undefined) day = Math.max(day, prev + space + 1);
    last.set(k, day);
  }
  return day;
}

